def ноша_у_края(от_края):
    """Доля полной ноши волоска или гребня в `от_края` px от края кисти: у самого края 0,2, в 7 px от края — 1.
    Один закон на каплю гребня (`укладка.py`, «полная») и на бок по сырому (`срастание.py`, `Край.несёт`)."""
    import numpy as np
    return 1.0 - 0.8 * np.clip((7.0 - от_края) / 7.0, 0.0, 1.0)

